key.query:
query GetBlogPosts($first: Int = 15, $after: String) {
  posts(
    first: $first
    after: $after
    where: {orderby: {field: DATE, order: DESC}}
  ) {
    pageInfo {
      hasNextPage
      endCursor
      __typename
    }
    nodes {
      databaseId
      slug
      date
      title(format: RENDERED)
      excerpt(format: RENDERED)
      content(format: RENDERED)
      categories {
        nodes {
          databaseId
          name
          slug
          __typename
        }
        __typename
      }
      featuredImage {
        node {
          sourceUrl
          mediaDetails {
            sizes {
              name
              sourceUrl
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
